Status alive(const PoliticalSubordinateAppointmentContext& x,const StableId& actor,Integer tick,const StableId& fact){auto p=read_actor_presence_before_fact(x.common,x.common_catalog,x.death_origin,actor,tick,fact);if(!p.ok)return {false,{},p.error};const auto* a=x.common.state().actors.find(actor);if(!p.value.alive||!a||!a->birth_tick||*a->birth_tick>tick||*a->birth_tick< -2147483647||tick<0||tick>2147483647||tick-*a->birth_tick<18*720)return common_failure("PoliticalSubordinateHistoricalAdultRequired",actor);return common_success();}
Status authority_before(const PoliticalSubordinateAppointmentContext& x,const PoliticalSubordinateAppointmentPolicy& p,const PoliticalSubordinateAppointmentOffer& offer,Integer tick,const StableId& fact,bool candidate_duty){const auto* head=x.heads.policies.find(p.head_succession_policy_id);if(!head)return common_failure("PoliticalSubordinateOriginalHeadRequired",fact);auto original=read_political_subordinate_office_before(x.common,x.organizations,x.organization_catalog,offer.head_office_id,tick,fact);if(!original.ok)return {false,{},original.error};if(original.value.office_epoch!=offer.head_epoch||original.value.holder_actor_id!=std::optional<StableId>{offer.issuer_actor_id})return common_failure("PoliticalSubordinateOriginalHeadRequired",fact);auto target=read_political_subordinate_office_before(x.common,x.organizations,x.organization_catalog,offer.office_id,tick,fact);if(!target.ok)return {false,{},target.error};if(target.value.office_epoch!=offer.target_epoch||target.value.holder_actor_id)return common_failure("PoliticalSubordinateActualVacancyRequired",fact);auto valid=grant(x,p,tick);if(!valid.ok)return valid;valid=x.seats(p,tick,fact);if(!valid.ok)return valid;valid=alive(x,offer.issuer_actor_id,tick,fact);if(!valid.ok)return valid;valid=validate_political_historical_member_duty(x.common,x.organizations,x.organization_catalog,{offer.organization_id,offer.head_office_id,offer.head_epoch,offer.issuer_actor_id},tick,fact,PoliticalMemberHistoryUse::political_subordinate_appointment);if(!valid.ok)return valid;if(candidate_duty){valid=alive(x,offer.candidate_actor_id,tick,fact);if(!valid.ok)return valid;valid=validate_political_historical_member_duty(x.common,x.organizations,x.organization_catalog,{offer.organization_id,{},0,offer.candidate_actor_id},tick,fact,PoliticalMemberHistoryUse::political_subordinate_appointment);if(!valid.ok)return valid;return qualification(x,p,offer.candidate_actor_id,tick,fact);}return common_success();}
bool closed_before(const PoliticalSubordinateAppointmentContext& x,const StableId& offer,const StableId& boundary){for(const auto& r:x.state.withdrawals.rows())if(r.second.offer_fact_id==offer&&before(x.common,r.first,boundary))return true;for(const auto& r:x.state.answers.rows())if(r.second.offer_fact_id==offer&&!r.second.accepted&&before(x.common,r.first,boundary))return true;const auto* a=answer(x.state,offer);if(a)for(const auto& r:x.state.arrivals.rows())if(r.second.acceptance_fact_id==a->id&&before(x.common,r.first,boundary))return true;return false;}
Outcome<bool> legacy_pending_before(const PoliticalSubordinateAppointmentContext& x,const PoliticalAppointment& old,Integer tick,const StableId& boundary){
 auto fail=[&]()->Outcome<bool>{return {false,false,common_failure("PoliticalSubordinateOriginalAppointmentHistoryRequired",old.id).error};};
 const auto cutoff=political_subordinate_appointment_fact_sequence(x.common,boundary);const auto* terms=x.politics_catalog.appointment_policies.find(old.policy_id);if(!cutoff||!terms||old.created_tick<0||old.created_tick>2147483647-terms->response_ticks)return fail();
 bool active=false;Integer deadline=old.created_tick+terms->response_ticks,prior=0,last_tick=-1;StableId last;
 for(const auto& row:x.politics.facts.rows()){const auto& f=row.second;if(f.appointment_id!=old.id)continue;const auto n=organization_instance_sequence(row.first,"politics");const auto* h=x.common.state().facts.find(row.first);if(f.id!=row.first||!n||*n>=x.common.state().next_instance_id||*n<=prior||!h||h->id!=f.id||h->kind!=f.kind||h->domain!="politics"||f.tick<last_tick||f.tick>x.common.tick()||(!last.empty()&&!before(x.common,last,f.id))||*n==*cutoff)return fail();const bool earlier=*n<*cutoff;if(earlier!=before(x.common,f.id,boundary)||(earlier&&f.tick>tick)||(!earlier&&f.tick<tick))return fail();
  if(earlier){if(f.status==AppointmentStatus::offered){if(f.id!=old.offered_fact_id||f.kind!="political_appointment_offered"||f.tick!=old.created_tick)return fail();active=true;}else if(f.status==AppointmentStatus::accepted){if(f.kind!="political_appointment_accepted"||f.tick>2147483647-terms->arrival_ticks)return fail();deadline=f.tick+terms->arrival_ticks;active=true;}else active=false;}
  prior=*n;last_tick=f.tick;last=f.id;
 }
 if(last.empty()||last!=old.last_fact_id)return fail();return {true,active&&tick<deadline,{}};
}
Status no_original_offer_overlap(const PoliticalSubordinateAppointmentContext& x){
 for(const auto& row:x.politics.appointments.rows()){const auto& old=row.second;const auto* header=x.common.state().facts.find(old.offered_fact_id);const auto n=organization_instance_sequence(old.offered_fact_id,"politics");if(!header||header->kind!="political_appointment_offered"||header->domain!="politics"||!n)return common_failure("PoliticalSubordinateOriginalAppointmentHistoryRequired",old.id);
  for(const auto& fresh:x.state.offers.rows()){const auto& offer=fresh.second;const auto* policy=x.catalog.policies.find(offer.policy_id);if(!policy||policy->jurisdiction_id!=old.jurisdiction_id)continue;const auto number=political_subordinate_appointment_fact_sequence(x.common,offer.id);if(!number||*number==*n||((*number<*n)!=before(x.common,offer.id,old.offered_fact_id))||(*number<*n?offer.tick>old.created_tick:offer.tick<old.created_tick))return common_failure("PoliticalSubordinateMixedOfferOrderMismatch",offer.id);
   if(*number<*n){Integer through=offer.response_until;if(const auto* a=answer(x.state,offer.id);a&&a->accepted&&before(x.common,a->id,old.offered_fact_id))through=a->arrival_until;if(old.created_tick<through&&!closed_before(x,offer.id,old.offered_fact_id))return common_failure("PoliticalSubordinateOriginalAppointmentOverlap",old.id);}
   else {auto pending=legacy_pending_before(x,old,offer.tick,offer.id);if(!pending.ok)return {false,{},pending.error};if(pending.value)return common_failure("PoliticalSubordinateOriginalAppointmentOverlap",offer.id);}
  }
 }
 return common_success();
}

